  "protocolVersion": "02.02",
  "name": "消息回声智能体",
  "description": "通过消息收件箱接收群组邀请，进入协作群组并接收任务，返回原消息、自身身份码和接收时间，回传任务状态。",
  "version": "0.1.0",
  "provider": {
    "name": "王骁逸"
  },
  "securitySchemes": {
    "mtls": {
      "type": "mutualTLS",
      "description": "使用 AIC clientAuth 证书建立 AMQPS 连接，接收收件箱邀请并参与协作群组。"
    }
  },
  "endPoints": [
    {
      "url": "amqps://wt.ioa.pub:5671/acps?inbox=inbox_{AIC}",
      "transport": "AMQP",
      "security": [
        {
          "mtls": []
        }
      ]
    }
  ],
  "capabilities": {
    "streaming": false,
    "notification": false,
    "messageQueue": [
      "amqp:0.9.1"
    ]
  },
  "defaultInputModes": [
    "application/json",
    "text/plain"
  ],
  "defaultOutputModes": [
    "application/json"
  ],
  "skills": [
    {
      "id": "interop.probe.echo",
      "name": "消息回传",
      "description": "接收 operation 为 read-only-probe 的 JSON 任务，读取 nonce，返回 nonce、partner_aic、observed_utc、result 和 business_mutations，并更新任务状态。",
      "version": "0.1.0",
      "tags": [
        "消息回传",
        "消息协作",
        "AMQPS Inbox",
        "AIP"
      ],
      "examples": [
        "{\"operation\": \"read-only-probe\", \"nonce\": \"hello-001\"}"
      ],
      "inputModes": [
        "application/json",
        "text/plain"
      ],
      "outputModes": [
        "application/json"
      ]
    }
  ]
}
